 const attentionItems=useMemo(()=>{const d=currentDate(),limit=(()=>{const x=new Date(d+"T12:00:00Z");x.setUTCDate(x.getUTCDate()+7);return x.toISOString().slice(0,10);})();const dueVocab=(data.vocabulary||[]).filter(v=>v.status!=="Archived"&&v.status!=="Mastered"&&(!(v.nextReviewDate||v.dueDate)||(v.nextReviewDate||v.dueDate)<=d)).map(v=>({key:"vocab-"+v.id,title:"مراجعة مفردة: "+v.term,detail:v.nextReviewDate||v.dueDate||"دون موعد",action:"vocab"}));const overdue=(data.lessons||[]).filter(l=>l.status!=="Skipped"&&l.status!=="Archived"&&l.status!=="Paused"&&l.studyDate&&l.studyDate<d&&lessonState(l).state!=="Completed").map(l=>({key:"lesson-"+l.id,title:"درس فائت: "+l.name,detail:"كان مخططًا في "+l.studyDate,action:"courses"}));const deadlines=(data.courses||[]).filter(x=>x.status!=="Archived"&&x.status!=="Paused"&&x.targetDate&&x.targetDate>=d&&x.targetDate<=limit&&computeCourseMetrics(x,data).state!=="Completed").map(x=>({key:"course-"+x.id,title:"موعد دورة قريب: "+x.name,detail:"الموعد "+x.targetDate,action:"courses"}));const stale=(data.areas||[]).filter(a=>a.isLanguage||a.category==="لغة").filter(a=>(data.assessments||[]).some(t=>t.areaId===a.id&&t.assessmentDate&&new Date(d+"T12:00:00Z").getTime()-new Date(t.assessmentDate+"T12:00:00Z").getTime()>Math.max(1,Number(data.preferences?.staleTestMonths)||12)*30*86400000)).map(a=>({key:"test-"+a.id,title:"حدّث اختبار مستوى: "+a.name,detail:"آخر اختبار أقدم من المدة المحددة",action:"placement"}));return [...overdue,...deadlines,...dueVocab,...stale].slice(0,12);},[data,learningStats]);
